package com.blackice.bc1.editor;
import org.junit.Test;
import static org.junit.Assert.*;
public class TransformEditsTest {
 @Test public void popInPreservesIndependentDimensionRatio(){for(float[] size:new float[][]{{2,1},{.05f,.0025f},{4,80},{70,70},{100,2000}}){Motion m=new Motion();float[] current=new float[Motion.COUNT];current[Motion.SCALE]=size[0];current[Motion.HEIGHT]=size[1];Keyframes.preset(m,"Pop In",0,2000,current);for(long t=0;t<=800;t+=17)assertEquals(size[1]/size[0],m.value(Motion.HEIGHT,t,0)/m.value(Motion.SCALE,t,0),1e-5);assertEquals(size[0],m.value(Motion.SCALE,600,0),0);assertEquals(size[1],m.value(Motion.HEIGHT,600,0),0);m.validate();}}
 @Test public void popInSupportsLegacyChannelArrays(){Motion m=new Motion();float[] current=new float[6];current[Motion.SCALE]=1;Keyframes.preset(m,"Pop In",0,2000,current);assertEquals(m.value(Motion.SCALE,200,0),m.value(Motion.HEIGHT,200,0),0);}
 @Test public void linkedScalePreservesCurrentProportion(){assertArrayEquals(new float[]{3,1.5f},TransformEdits.scalePair(2,1,Motion.SCALE,3,true),1e-6f);assertArrayEquals(new float[]{1,.5f},TransformEdits.scalePair(2,1,Motion.SCALE,1,true),1e-6f);assertArrayEquals(new float[]{2,1},TransformEdits.scalePair(3,1.5f,Motion.HEIGHT,1,true),1e-6f);}
 @Test public void unlockedDimensionsAreIndependent(){assertArrayEquals(new float[]{3,1},TransformEdits.scalePair(2,1,Motion.SCALE,3,false),0);assertArrayEquals(new float[]{2,3},TransformEdits.scalePair(2,1,Motion.HEIGHT,3,false),0);}
 @Test public void separatingLegacyHeightPreservesEveryFrame(){EditProject.Clip c=new EditProject.Clip();c.aspect=.6f;c.scale=.8f;Motion.Key k=new Motion.Key(100,1);Keyframes.ease(k,3);c.motion.put(Motion.SCALE,k);c.motion.put(Motion.SCALE,new Motion.Key(1100,3));EditProject.Clip old=c.copy();TransformEdits.separateHeight(c);for(long t=0;t<1300;t+=17){TransformMath.Transform before=TransformMath.of(old,t),after=TransformMath.of(c,t);assertArrayEquals(TransformMath.matrix(before),TransformMath.matrix(after),1e-6);}assertEquals(.8f*.6f,c.heightScale,1e-6);assertEquals(2,c.motion.curves.get(Motion.HEIGHT).size());}
 @Test public void independentHeightAndFullTurnsSurviveStorage()throws Exception{EditProject p=new EditProject();EditProject.Overlay o=new EditProject.Overlay();o.endMs=3000;p.overlays.add(o);o.heightScale=1.2f;o.motion.put(Motion.HEIGHT,new Motion.Key(0,.5f));o.motion.put(Motion.HEIGHT,new Motion.Key(2000,1.5f));Motion.Key start=new Motion.Key(0,0);Keyframes.ease(start,0);o.motion.put(Motion.ROTATION,start);o.motion.put(Motion.ROTATION,new Motion.Key(2000,-720));EditProject.Overlay loaded=ProjectStore.decode(ProjectStore.encode(p)).overlays.get(0);assertEquals(-360,TransformMath.of(loaded,1000).rotation,.01);assertEquals(-720,TransformMath.of(loaded,2000).rotation,0);assertEquals(1.5,TransformMath.of(loaded,2000).scale*TransformMath.of(loaded,2000).aspect,1e-6);}
 @Test public void tenChannelProjectsStillLoad()throws Exception{EditProject p=new EditProject();EditProject.Overlay o=new EditProject.Overlay();o.endMs=3000;o.aspect=1.7f;p.overlays.add(o);org.json.JSONObject json=new org.json.JSONObject(ProjectStore.encode(p));org.json.JSONObject layer=json.getJSONArray("overlays").getJSONObject(0);layer.remove("heightScale");layer.getJSONArray("motion").remove(10);EditProject.Overlay loaded=ProjectStore.decode(json.toString()).overlays.get(0);assertEquals(-1,loaded.heightScale,0);assertEquals(1.7,TransformMath.of(loaded,100).aspect,1e-6);}
 @Test public void pointerWrapAccumulatesMultipleTurns(){float sum=359;sum+=TransformEdits.angleDelta(179,-179);assertEquals(361,sum,0);sum=0;float last=-90;for(int i=1;i<=32;i++){float next=-90+i*45;next=(next+180)%360-180;sum+=TransformEdits.angleDelta(last,next);last=next;}assertEquals(1440,sum,0);assertEquals(-2,TransformEdits.angleDelta(-179,179),0);}
 @Test public void rejectInvalidScaleWithoutMutation(){for(float bad:new float[]{0,-1,Float.NaN,Float.POSITIVE_INFINITY,100000}){try{TransformEdits.scalePair(2,1,Motion.SCALE,bad,true);fail();}catch(IllegalArgumentException expected){}}}
 @Test public void rotationHasNoTurnCap(){assertTrue(Motion.allowed(Motion.ROTATION,10800));assertTrue(Motion.allowed(Motion.ROTATION,-10800));Motion m=new Motion();Motion.Key a=new Motion.Key(0,-Float.MAX_VALUE);Keyframes.ease(a,0);m.put(Motion.ROTATION,a);m.put(Motion.ROTATION,new Motion.Key(1000,Float.MAX_VALUE));assertTrue(Float.isFinite(m.value(Motion.ROTATION,500,0)));}
 @Test public void heightKeyNavigationExcludesRotation(){Motion m=new Motion();m.put(Motion.HEIGHT,new Motion.Key(200,1));m.put(Motion.ROTATION,new Motion.Key(100,90));assertEquals(200,Keyframes.adjacent(m,0,true,Motion.SCALE,Motion.HEIGHT));assertEquals(-1,Keyframes.adjacent(m,200,true,Motion.SCALE,Motion.HEIGHT));}
}
